// Okunan her dosya için hedef yolu hesaplar: /files/yedek/YYYY-AA-GG-<ad>
// Binary veri olduğu gibi taşınır — dosya içeriğine dokunulmaz.
//
// Tarih neden klasör değil de dosya adının başında? n8n'in dosya yazma düğümü
// var olmayan bir klasörü kendiliğinden oluşturmaz; her gece yeni bir klasör
// açmaya çalışmak ilk gece hata verirdi. `local-files/yedek/` klasörü depoyla
// birlikte geldiği için bu yol her zaman çalışır.
const ilk = $input.first().json || {};
if (ilk.error) {
  const m = String(ilk.error.message || ilk.error);
  if (/ENOENT|no such file|not found/i.test(m)) {
    throw new Error('local-files klasöründe yedeklenecek .json dosyası bulunamadı. README §3\'teki kopyalama adımını tamamladınız mı?');
  }
  throw new Error('Yedeklenecek dosyalar okunamadı → ' + m);
}

const d = new Date();
const gun = d.getFullYear() + '-' +
  String(d.getMonth() + 1).padStart(2, '0') + '-' +
  String(d.getDate()).padStart(2, '0');

return $input.all().map((item) => {
  const bin = (item.binary && item.binary.data) || {};
  const ad = String(bin.fileName || 'bilinmeyen.json').split('/').pop();
  return {
    json: { hedef: '/files/yedek/' + gun + '-' + ad, kaynakAd: ad, gun },
    binary: item.binary,
  };
});

// n8n workflow'larını da yedeklemek isteğe bağlıdır: .env içinde N8N_API_KEY
// doluysa panel API'sinden hepsi çekilir. Boşsa bu dal sessizce atlanır.
const anahtar = String($env.N8N_API_KEY || '').trim();
if (!anahtar) return [];
const gun = $input.first().json.gun;
return [{ json: { gun } }];

// API yanıtını yedeklenecek tek bir JSON'a dönüştürür.
const yanit = $input.first().json || {};
if (yanit.error) {
  const ham = String(yanit.error.message || yanit.error);
  throw new Error('n8n API\'sinden workflow listesi alınamadı (N8N_API_KEY doğru mu?) → ' + ham.slice(0, 200));
}
const liste = Array.isArray(yanit.data) ? yanit.data : [];
return [{ json: { alindi: new Date().toISOString(), adet: liste.length, workflows: liste } }];
